content.content:
        lengths.reserveCapacity(model.tokens.count)
        func extend(_ ranges: inout [NSRange], _ range: NSRange) {
            if let last = ranges.last, NSMaxRange(last) >= range.location - 1 {
                ranges[ranges.count - 1] = NSUnionRange(last, range)
            } else {
                ranges.append(range)
            }
        }
        for paragraph in model.paragraphs {
            let stamp = ReelTime.format(paragraph.start, fps: fps, frames: frames)
            timecodes.append(NSRange(location: plain.length, length: (stamp as NSString).length))
            plain.append(stamp)
            plain.append("\n")
            for index in paragraph.firstToken..<paragraph.endToken {
                let token = model.tokens[index]
                if index > paragraph.firstToken { plain.append(" ") }
                if token.collapsedBefore > 0 {
                    extend(&faint, NSRange(location: plain.length, length: 2))
                    plain.append("⋯ ")
                }
                let range = NSRange(location: plain.length, length: (token.word.text as NSString).length)
                plain.append(token.word.text)
                starts.append(range.location)
                lengths.append(range.length)
                if token.struck {
                    extend(&struck, range)
                } else if !token.word.editable {
                    extend(&faint, range)
                }
                if !token.word.editable, let why = token.word.why {
                    if let last = dim.last, last.why == why, index > paragraph.firstToken,
                        !model.tokens[index - 1].word.editable
                    {
                        dim[dim.count - 1].range = NSUnionRange(last.range, range)
                    } else {
                        dim.append((range, why))
                    }
                }
                if let pause = pauseAfter[index] {
                    let seconds = Double(pause.span.end - pause.span.start) / Double(ReelTime.perSecond)
                    let label = String(format: "[%.1f s]", seconds)
                    plain.append(" ")
                    paused.append(NSRange(location: plain.length, length: (label as NSString).length))
                    plain.append(label)
                }
            }
            plain.append("\n")
        }
        let out = NSMutableAttributedString(string: plain as String, attributes: wordAttributes)
        let faintColor = resolved(DS.textFaint)
        for range in faint { out.addAttribute(.foregroundColor, value: faintColor, range: range) }
        for range in struck {
            out.addAttributes(
                [.foregroundColor: faintColor, .strikethroughStyle: NSUnderlineStyle.single.rawValue],
                range: range)
        }
        let pauseColor = resolved(DS.textMuted)
        for range in paused { out.addAttribute(.foregroundColor, value: pauseColor, range: range) }
        let timecode = timecodeAttributes
        for range in timecodes {
            out.setAttributes(timecode, range: NSRange(location: range.location, length: range.length + 1))
        }
        tokenStarts = starts
        tokenLengths = lengths
        timecodeRanges = timecodes
        dimRuns = dim
        pauseRanges = paused
        return out
    }

    /// A system colour as concrete sRGB in the view's appearance: TextKit 2
    /// draws a dynamic colour (`labelColor`) into a `CGContext` as nothing
    /// (measured, TX-S2), so the text is styled with resolved colours and
    /// restyled when the appearance changes.
    func resolved(_ color: NSColor) -> NSColor {
        var out = color
        effectiveAppearance.performAsCurrentDrawingAppearance {
            out = color.usingColorSpace(.sRGB) ?? color
        }
        return out
    }

    var wordAttributes: [NSAttributedString.Key: Any] {
        let style = NSMutableParagraphStyle()
        style.lineSpacing = 2
        style.paragraphSpacing = 12
        return [.font: DS.sans(13), .foregroundColor: resolved(DS.textStrong), .paragraphStyle: style]
    }

    var timecodeAttributes: [NSAttributedString.Key: Any] {
        let style = NSMutableParagraphStyle()
        style.paragraphSpacing = 2
        return [.font: DS.mono(10), .foregroundColor: resolved(DS.textMuted), .paragraphStyle: style]
    }

    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        guard let style = shownStyle else { return }
        show(model, pauses: pauses, fps: style.fps, timecodeFrames: style.frames)
    }

import Foundation

/// What the Transcript tab shows, and its fill (road map "creator-jobs" TX2a,
/// spec §11 TX-22): the edited container's words as `TranscriptTokens`, the
/// clips with no words, the notes and the status line, rebuilt from a
/// per-media words cache, with this Mac's misses read by the tab's ONE
/// `TranscriptFill` owner (TX-12).
///
/// Main thread, but for two serial `.utility` queues of its own: the LOAD
/// queue reads a media's cloud transcript (TR-11), else its stored run, then
/// its pause set; the WAIT queue runs the one waiter, which wants the first
/// pending miss, waits for it and moves on — never the load queue, so a load
/// never waits behind a fill. Each media's words show as soon as its run is
/// stored, not when the last one ends.
///
/// `pending` (the misses in the fill's order, the media under the playhead
/// first) and the waiter's state are guarded by `lock`; `update()` replaces
/// `pending`, and releases the want when the media the waiter waits on is no
/// longer needed, which `wait` answers as `.cancelled`.
///
/// The bar's view state (TX2b, spec §11 TX-25, TX-26) is here too: Words from
/// (one track, or all), Language (an installed one, or the Mac's default),
/// and Stop, which withdraws only the tab's want, and Read.
///
/// Since TX3a (spec §11 TX-30) each media's voice cache is kept beside its
/// pause set, every read word (`allWords`, before Words from) beside the
/// model, and `cutTable()` is the cut's table, made once per rebuild.
///
/// Since TX1b (TX-18) a voice or peaks cache landing re-reads that `.apple`
/// media's words (`reloadDeviceWords`), kept shown until it merges; a load
/// that read before a landing (its epoch moved) is read again, not merged.
final class TranscriptTabSource {
    enum Status: Equatable {
        case idle, loading, reading(name: String, fraction: Double, index: Int, of: Int), noModel
        case failed([String])
        case stopped(remaining: Int)
    }

    private weak var document: ProjectDocument?
    private let onChange: () -> Void
    private(set) var model = TranscriptTokens.empty
    private(set) var noWords: [TimelineTranscript.NoWords] = []
    private(set) var notes: [String] = []
    private(set) var status: Status = .idle
    private(set) var rebuilds = 0
    /// Every read word of the edited container, before Words from (TX-32).
    private(set) var allWords: [TimelineTranscript.Word] = []
    private(set) var lastRebuildMilliseconds: Double = 0

    /// Words from: nil is All tracks (TX-25).
    private(set) var wordsFrom: UInt32?
    /// Language: a BCP-47 identifier; nil is Automatic, the Mac's default.
    private(set) var language: String?
    /// The edited container's tracks, from the last read, in snapshot order.
    private(set) var tracks: [TrackSnapshot] = []
    /// The installed languages; nil until read off main.
    private(set) var languages: [Transcriber.Language]?
    /// Stop was pressed and neither Read nor a show has come since (TX-26).
    private(set) var stopped = false

    /// Whether Stop applies: the tab's waiter reads on this Mac.
    var canStop: Bool {
        if case .reading = status { return true }
        return false
    }

    /// Whether the tab's owner wants a media of the fill now.
    var ownsWant: Bool {
        lock.lock()
        defer { lock.unlock() }
        let k: Int
    }

    /// One word of a media, in its SOURCE ticks. An on-device word's
    /// `source` is its MOVED start (TX-15); `recognisedStart` is the
    /// recogniser's own when TX-15 moved it.
    struct SourceWord: Equatable {
        let text: String
        let source: Ticks
        let sourceEnd: Ticks
        let speaker: String?
        var recognisedStart: Ticks? = nil

        /// The tick an identity, a cut's match and a pause set key by
        /// (TX-17): the recogniser's start, moved or not.
        var identityTick: Ticks { recognisedStart ?? source }
    }

    /// A heard media's words and where they came from.
    struct MediaWords: Equatable {
        let media: UInt32
        let engine: TranscriptionEngine
        let language: String?
        let fillersReported: Bool
        let words: [SourceWord]
        /// An on-device media read with no voice cache: its starts are the
        /// recogniser's, unmoved (TX-18).
        var voiceCacheMissing: Bool = false
    }

    /// One heard instance: a plan audio segment, its inner clip, that clip's
    /// job (in its own container's time) and the CONTAINER track it plays
    /// under, with that track's stacking index.
    struct Instance: Equatable {
        let segment: PlanSegment
        let clip: ClipSnapshot
        let job: Transcriber.Job
        let track: UInt32
        let trackIndex: Int
    }

    /// A media clip the gate refuses, and why.
    struct NoWords: Equatable {
        let clip: UInt32
        let nestPath: [UInt32]
        let tag: String
        let reason: String
    }

    /// One word on the timeline.
    struct Word: Equatable {
        let text: String
        let start: Ticks
        let end: Ticks
        let clip: UInt32
        let track: UInt32
        let media: UInt32
        let engine: TranscriptionEngine
        let filler: Bool
        let speaker: String?
        let editable: Bool
        let why: String?
        let id: Identity
    }

    /// The words one answer carries at most (TX-13).
    static let pageLimit = 2000

    // MARK: - Source words

    /// A cached media transcript's words: each word's start and
    /// `max(start, end)` through `MediaTranscript.sourceTicks`, the one door.
    static func sourceWords(cloud file: MediaTranscript.File) -> [SourceWord] {
        file.words.map {
            SourceWord(
                text: $0.text, source: MediaTranscript.sourceTicks(milliseconds: $0.start),
                sourceEnd: MediaTranscript.sourceTicks(milliseconds: max($0.start, $0.end)),
                speaker: $0.speaker)
        }
    }

