/// The inspector's foot (spec §11 CI-10): "Refused: " and the rule's own
/// sentence, VERBATIM, when the core refused a person's edit.
/// `ProjectDocument.applyEdit` has already beeped; this is the one thing a
/// person sees that an identity does not show them.
///
/// It lasts until the PROJECT changes — `clearIfStale` runs at the top of
/// every inspector refresh and clears it once `editedProject` is another
/// handle, which is an applied edit, an undo, a redo or a scope change — or
/// until it is clicked. A playhead or selection move keeps the same handle,
/// so it keeps the strip. Hidden, it is detached from the foot's stack, so
/// it takes no room.
final class InspectorRefusalStrip: NSView {
    private(set) var text: String?
    /// The handle the refusal was shown under. Weak: a handle nothing else
    /// holds is one the project has moved away from, and nil is not it.
    private weak var project: ReelProject?
    private let label = NSTextField(wrappingLabelWithString: "")
    /// Its width pinned to the foot's, made on a show: hidden, the strip is
    /// detached from the foot's stack, and a constraint made once in
    /// `loadView` need not survive that.
    private var spanning: NSLayoutConstraint?

    init() {
        super.init(frame: .zero)
        wantsLayer = true
        isHidden = true
        label.font = DS.sans(11)
        label.textColor = DS.textStrong
        label.isSelectable = false
        label.maximumNumberOfLines = 3
        label.cell?.truncatesLastVisibleLine = true
        label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        label.translatesAutoresizingMaskIntoConstraints = false
        addSubview(label)
        NSLayoutConstraint.activate([
            label.topAnchor.constraint(equalTo: topAnchor, constant: 8),
            label.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -8),
            label.leadingAnchor.constraint(
                equalTo: leadingAnchor, constant: InspectorMetrics.inset),
            label.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRefusalStrip does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    /// A wrapping label needs its width to know its height.
    override func layout() {
        super.layout()
        let width = max(bounds.width - 2 * InspectorMetrics.inset, 0)
        guard label.preferredMaxLayoutWidth != width else { return }
        label.preferredMaxLayoutWidth = width
        super.layout()
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.hoverFill.setFill()
        bounds.fill()
        DS.border.setFill()
        NSRect(x: 0, y: 0, width: bounds.width, height: 1).fill()
    }

    func show(_ refusal: ReelRefusal, under project: ReelProject?) {
        let sentence = "Refused: " + refusal.reason
        text = sentence
        self.project = project
        label.stringValue = sentence
        toolTip = sentence
        isHidden = false
        needsDisplay = true
    }

    /// Clears once the project is not the handle the refusal was shown under.
    func clearIfStale(_ project: ReelProject?) {
        guard text != nil, project !== self.project else { return }
        clear()
    }

    func clear() {
        guard text != nil else { return }
        text = nil
        project = nil
        label.stringValue = ""
        toolTip = nil
        isHidden = true
    }

    override func mouseDown(with event: NSEvent) {
        clear()
    }

    /// Pins the strip to `container`'s width unless that pin is still active.
    func span(_ container: NSView) {
        guard spanning?.isActive != true, isDescendant(of: container) else { return }
        spanning = widthAnchor.constraint(equalTo: container.widthAnchor)
        spanning?.isActive = true
    }
}

extension InspectorViewController {
    /// The editor's forward of `projectDocumentDidRefuse`.
## The bar

A bar sits above the text and stays put while the text scrolls.

- **Words from** chooses whose words to show: **All tracks**, or one track by
  name. With one track chosen, the tab shows only the words on it, and reads
  only the files with a clip on it. If that track goes away, the tab goes
  back to All tracks.
- **Language** chooses the language files are read in on this Mac:
  **Automatic** (your Mac's language, shown in brackets as a code such as
  en-US) or any language your Mac has a speech model for. Choosing one reads
  the files again in that language; the earlier reading is kept too, so
  switching back is immediate. A file with an AssemblyAI transcript keeps
  showing that transcript whichever you choose.

Both choices belong to the window: they stay while it is open, whichever tab
you look at, and are not saved with the project.

Under the two popups, short notes say what the tab is doing and anything it
could not read:

- **Reading “name” on this Mac… 40 % (1 of 2)** while a file is being
  transcribed, with a **Stop** button beside it.
- **Stopped. 2 files not read on this Mac.** after you press Stop, with a
  **Read** button that carries on.
- When two tracks carry the same speech, a note names the two clips, so you
  can mute one.
- A clip with no words is listed with the reason, such as "clip 12 — its audio
  is switched off" or a clip that plays in reverse. The first three are
  listed; "…and 4 more clips with no words." stands for the rest, and holding
  the pointer over it lists them.


## What the range is

The range is a span shaded across the ruler and the lanes. It changes nothing by itself. These commands read it:

| Command | What it does with the range |
| --- | --- |
| [Loop](/timeline/loop/) | Plays the range over and over, instead of the whole timeline. |
| <kbd>⌫</kbd> and <kbd>⌘⌫</kbd> | With no clip selected, [Lift or Ripple Delete](/editing/delete-clips/) the range. With nothing selected and no range, they beep. |
| [Speed ramp presets](/speed/make-a-ramp/) | Cover the range when it lies entirely inside the clip. |
| [**Insert ▸ Adjustment Clip**](/color/adjustment-clips/) | Covers the range. With no range it covers the selected clips, or the whole timeline. |
| [Export](/export/range/) | Writes only the range when you set **Range:** to **In/out range**. |
| [Retime Range](/speed/retime-range/) | Changes the speed of everything in the range. |
| [New Project from Range](/projects/new-project-from-range/) | Opens a new project made of the range. |
| [Generate Captions](/captions/generate-captions/) | Offers **In/out range** under **From**, which takes every clip that overlaps the range, whole. |
| [Switch by Speaker](/multicam/switch-by-speaker/) | Works over the range. With no range it works over the selected angle clips. |

Two other things set the range for you. Selecting words in the [Transcript tab](/captions/delete-words/) makes them the range, and clearing that selection clears it. **Preview** for a [motion preset](/motion/motion-presets/) sets the range to the clip and turns Loop on, and both stay until you clear them.

